<script setup lang="ts">
import type { BsBillingCopy, BsBillingView, BsBillingForm, BsManualPaymentView, BsPlanImpactView } from '../types/billingPresentation'
withDefaults(defineProps<{ variant?: 'default' | 'shop'; copy: BsBillingCopy; view: BsBillingView; manual?: BsManualPaymentView; impact?: BsPlanImpactView; showHeader?: boolean }>(), { variant: 'default', showHeader: true, manual: undefined, impact: undefined })
const form = defineModel<BsBillingForm>('form', { required: true })
const evidenceFile = defineModel<File | null>('evidenceFile', { default: null })
const emit = defineEmits<{ checkout: []; checkoutRefresh: []; checkoutContinue: []; checkoutRenew: []; retry: []; usageRetry: []; pricingRetry: []; interval: [value: string]; variant: [id: string, value: string]; plan: [id: string]; manualPlan: [id: string]; privatePreview: []; privateClear: []; transferOpen: []; transferClose: []; transferSubmit: []; evidenceSelect: [event: Event]; evidenceUpload: []; requests: []; manualClose: []; manualRefresh: []; manualSelect: [id: string]; manualFile: [event: Event]; manualSubmit: []; manualCancel: []; manualDownload: [id: string]; openSubscription: []; impactClose: [] }>()
function field(key: keyof BsBillingForm, value: string | number | null | undefined) { form.value = { ...form.value, [key]: key === 'paidAmount' ? Number(value) : String(value ?? '') } }
</script>
<template>
  <BsStack gap="lg" class="bs-billing-page" :class="{ 'bs-billing-page--shop': variant === 'shop' }">
    <BsPageHeader v-if="showHeader !== false" :title="copy.title" :subtitle="copy.subtitle"><template #actions><BsText v-if="view.workspace" size="xs" emphasis="semibold">{{ view.workspace }}</BsText></template></BsPageHeader>
    <BsStateSurface v-if="view.denied" state="denied" :title="copy.denied"/>
    <BsSectionSkeleton v-else-if="view.loading" variant="cards"/>
    <BsStateSurface v-else-if="view.failed" state="error" :title="copy.failed" :action-label="copy.retry" @action="emit('retry')"/>
    <template v-else-if="view.available">
      <BsSectionNavigation v-if="variant === 'shop'" :label="copy.title" :sections="[{ id: 'current-plan', label: copy.current || copy.title }, { id: 'usage', label: copy.usage }, { id: 'plans', label: copy.compare }, ...(view.checkout || view.instructions || view.transfer || view.showEvidence ? [{ id: 'payment', label: copy.payment || copy.instructions }] : []), ...(view.showHistory ? [{ id: 'history', label: copy.history }] : [])]" />
      <BsContentSection v-if="variant === 'shop'" id="current-plan" :title="copy.current || copy.title">
      <BsGrid :columns="4"><BsKpiCard v-for="metric in view.summary" :key="metric.id" :title="metric.label"><BsStatusBadge v-if="metric.status" :status="metric.status"/><BsText size="lg" emphasis="semibold">{{ metric.value }}</BsText><BsText v-if="metric.note" size="xs" tone="muted">{{ metric.note }}</BsText></BsKpiCard></BsGrid>
      </BsContentSection>
      <BsGrid v-if="variant !== 'shop'" :columns="4"><BsKpiCard v-for="metric in view.summary" :key="metric.id" :title="metric.label"><BsStatusBadge v-if="metric.status" :status="metric.status"/><BsText size="lg" emphasis="semibold">{{ metric.value }}</BsText><BsText v-if="metric.note" size="xs" tone="muted">{{ metric.note }}</BsText></BsKpiCard></BsGrid>
      <BsDescriptionList v-if="view.details.length" :columns="2"><BsBox v-for="detail in view.details" :key="detail.label"><BsDescriptionTerm>{{ detail.label }}</BsDescriptionTerm><BsDescriptionValue>{{ detail.value }}</BsDescriptionValue></BsBox></BsDescriptionList>
      <BsText v-if="view.notice" role="status" tone="warning">{{ view.notice }}</BsText><BsText v-if="view.providerNotice" tone="muted">{{ view.providerNotice }}</BsText>
      <BsContentSection v-if="variant !== 'shop' && view.latest" :title="view.latest.title" aria-live="polite"><BsInline><BsStatusBadge :status="view.latest.status"/><BsText emphasis="semibold">{{ view.latest.statusLabel }}</BsText><BsText tone="muted">{{ view.latest.summary }}</BsText></BsInline><BsText>{{ view.latest.message }}</BsText><BsText v-if="view.latest.reason" tone="muted">{{ copy.reviewReason }}: {{ view.latest.reason }}</BsText></BsContentSection>
      <BsContentSection id="usage" :title="copy.usage" :description="copy.usageHelp"><BsStateSurface v-if="view.usage.loading && !view.usage.items.length" state="loading" :title="copy.usageLoading"/><BsStateSurface v-else-if="view.usage.failed && !view.usage.items.length" state="error" :title="copy.usageError" :action-label="copy.retry" @action="emit('usageRetry')"/><template v-else><BsButton v-if="view.usage.failed" variant="link" @click="emit('usageRetry')">{{ copy.retry }}</BsButton><BsUsageMeterGrid :items="view.usage.items"/></template></BsContentSection>
      <BsContentSection id="plans" :title="copy.compare" :description="copy.compareHelp"><BsBox :data-testid="view.pricing.sectionTestId">
        <BsPanel v-if="view.trial" data-testid="trial-summary" padding="lg"><BsHeading :level="2">{{ view.trial.title }}</BsHeading><BsText>{{ view.trial.body }}</BsText><BsText tone="muted">{{ view.trial.date }}</BsText><BsText tone="muted">{{ view.trial.note }}</BsText></BsPanel>
        <BsButton v-if="view.canRequests" @click="emit('requests')">{{ copy.requests }}</BsButton>
        <BsMarketingPricing :variant="view.pricing.variant" :plans="view.pricing.plans" :interval="view.pricing.interval" :interval-options="view.pricing.intervalOptions" :copy="view.pricing.copy" :annual-saving="view.pricing.annualSaving" :intro="view.pricing.intro" :loading="view.pricing.loading" :error="view.pricing.error" :columns="view.pricing.columns" :test-id="view.pricing.testId" @update:interval="emit('interval', $event)" @update:variant="(id, value) => emit('variant', id, value)" @action="emit('plan', $event)" @secondary-action="emit('manualPlan', $event)" @retry="emit('pricingRetry')"/>
        <BsText v-if="view.policy" data-testid="checkout-policy-review" role="note">{{ view.policy.beforeTerms }} <BsLink to="/terms" target="_blank" rel="noopener">{{ view.policy.terms }}</BsLink>{{ view.policy.beforeRefund }} <BsLink to="/refund-cancellation" target="_blank" rel="noopener">{{ view.policy.refund }}</BsLink>{{ view.policy.beforePrivacy }} <BsLink to="/privacy" target="_blank" rel="noopener">{{ view.policy.privacy }}</BsLink>{{ view.policy.afterPrivacy }}</BsText>
        <BsText v-if="view.paymentNotice" data-testid="payment-method-branding" role="note">{{ view.paymentNotice }}</BsText><BsText v-if="view.paymentRequired" size="xs" tone="muted">{{ view.paymentRequired }}</BsText><BsText v-if="view.compatibilityNotice" role="note" tone="muted">{{ view.compatibilityNotice }}</BsText><BsText v-if="view.pricingError" role="alert" tone="danger">{{ view.pricingError }}</BsText>
      </BsBox></BsContentSection>
      <BsDisclosure v-if="variant === 'shop' && view.privateOffer" :summary="copy.privateTitle" variant="surface">
      <BsContentSection v-if="view.privateOffer" data-private-offer :title="copy.privateTitle" :description="copy.privateHelp"><BsForm :pending="view.privateOffer.pending" :error="view.privateOffer.error" @submit="emit('privatePreview')"><BsField v-slot="control" :label="copy.privateLink"><BsInput :id="control.id" :model-value="form.privateLink" type="password" autocomplete="off" maxlength="2048" @update:model-value="value => field('privateLink', value)"/></BsField><BsButton type="submit" :pending="view.privateOffer.pending">{{ copy.privatePreview }}</BsButton></BsForm><BsStack v-if="view.privateOffer.title" data-private-offer-preview><BsHeading :level="3">{{ view.privateOffer.title }}</BsHeading><BsText>{{ view.privateOffer.summary }}</BsText><BsList><BsListItem v-for="limit in view.privateOffer.limits" :key="limit.key">{{ limit.label }}: {{ limit.value }}</BsListItem></BsList><BsText v-if="view.privateOffer.notice" role="status">{{ view.privateOffer.notice }}</BsText><BsText v-if="view.privateOffer.redeemed" role="status">{{ view.privateOffer.redeemed }}</BsText><BsButton variant="text" @click="emit('privateClear')">{{ copy.privateClear }}</BsButton></BsStack></BsContentSection>
      </BsDisclosure>
      <section v-if="variant === 'shop'" id="payment" class="bs-billing-payment" :aria-label="copy.payment || copy.instructions">
      <BsContentSection v-if="view.checkout" data-testid="hosted-checkout" :title="view.checkout.title" :description="view.checkout.description">
        <span role="img" :aria-label="view.checkout.logoAlt" class="bs-billing-provider-logo"><BsImage class="bs-billing-provider-logo__light" :src="view.checkout.logoLight" alt="" :width="147" :height="24" fit="contain"/><BsImage class="bs-billing-provider-logo__dark" :src="view.checkout.logoDark" alt="" :width="147" :height="24" fit="contain"/></span>
        <BsText v-if="view.checkout.quote" emphasis="semibold">{{ view.checkout.quote }}</BsText>
        <BsText v-if="view.checkout.notice" role="note">{{ view.checkout.notice }}</BsText>
        <BsText v-if="view.checkout.disabled && view.checkout.unavailable" role="status" tone="muted">{{ view.checkout.unavailable }}</BsText>
        <BsText v-if="view.checkout.error" role="alert" tone="danger">{{ view.checkout.error }}</BsText>
        <BsText v-if="view.checkout.statusMessage" data-testid="checkout-state" role="status">{{ view.checkout.statusMessage }}</BsText>
        <BsInline gap="sm">
        <BsButton v-if="view.checkout.actionVisible !== false" :disabled="view.checkout.disabled" :pending="view.checkout.pending" @click="emit('checkout')">{{ view.checkout.action }}</BsButton>
        <BsButton v-if="view.checkout.continueLabel" variant="primary" @click="emit('checkoutContinue')">{{ view.checkout.continueLabel }}</BsButton>
        <BsLink v-if="view.checkout.helpLabel && view.checkout.helpTo" :to="view.checkout.helpTo">{{ view.checkout.helpLabel }}</BsLink>
        <BsButton v-if="view.checkout.renewLabel" variant="text" :disabled="view.checkout.pending" @click="emit('checkoutRenew')">{{ view.checkout.renewLabel }}</BsButton>
        </BsInline>
        <BsText size="sm" tone="muted">{{ copy.policyPrefix }} <BsLink to="/terms">{{ copy.terms }}</BsLink> · <BsLink to="/privacy">{{ copy.privacy }}</BsLink> · <BsLink to="/refund-cancellation">{{ copy.refund }}</BsLink>.</BsText>
      </BsContentSection>
      <BsContentSection v-if="view.latest" :title="view.latest.title" class="bs-billing-payment__status" aria-live="polite"><BsInline><BsStatusBadge :status="view.latest.status"/><BsText emphasis="semibold">{{ view.latest.statusLabel }}</BsText><BsText tone="muted">{{ view.latest.summary }}</BsText></BsInline><BsText>{{ view.latest.message }}</BsText><BsText v-if="view.latest.reason" tone="muted">{{ copy.reviewReason }}: {{ view.latest.reason }}</BsText></BsContentSection>
      <BsContentSection v-if="view.instructions" :title="copy.instructions" :description="copy.instructionsHelp"><BsText size="xs" emphasis="semibold">{{ copy.manual }}</BsText><BsGrid v-if="view.instructions.recipient || view.instructions.link || view.instructions.qr || view.instructions.text" :columns="2"><BsBox v-if="view.instructions.recipient"><BsText tone="muted">{{ copy.recipient }}</BsText><BsText dir="ltr" emphasis="bold">{{ view.instructions.recipient }}</BsText></BsBox><BsBox v-if="view.instructions.link"><BsText tone="muted">{{ copy.paymentLink }}</BsText><BsLink :to="view.instructions.link" target="_blank" rel="noopener noreferrer" external>{{ view.instructions.link }}</BsLink></BsBox><BsBox v-if="view.instructions.qr"><BsText tone="muted">{{ copy.qr }}</BsText><BsImage :src="view.instructions.qr" :alt="copy.qr"/></BsBox><BsText v-if="view.instructions.text">{{ view.instructions.text }}</BsText></BsGrid><BsText v-else tone="muted">{{ copy.instructionsUnavailable }}</BsText></BsContentSection>
      <BsContentSection v-if="view.transfer" :title="copy.notice" :description="copy.noticeHelp"><BsButton :disabled="view.transfer.disabled" @click="emit('transferOpen')">{{ copy.submit }}</BsButton></BsContentSection>
      <BsContentSection v-if="view.showEvidence" data-payment-evidence :title="copy.evidenceTitle" :description="copy.evidenceHelp"><BsStack v-if="view.evidence"><BsText>{{ copy.reference }}: {{ view.evidence.reference }}</BsText><BsForm :pending="view.evidence.pending" :error="view.evidence.error" @submit="emit('evidenceUpload')"><BsField for="payment-receipt" :label="copy.evidenceSelect"><BsFileInput :key="view.evidence.inputVersion" input-id="payment-receipt" :model-value="evidenceFile" :label="copy.evidenceSelect" accept="image/jpeg,image/png,image/webp" required @change="emit('evidenceSelect', $event)"/></BsField><BsButton type="submit" :pending="view.evidence.pending" :disabled="!evidenceFile">{{ view.evidence.pending ? copy.evidenceUploading : copy.evidenceUpload }}</BsButton></BsForm><BsText v-if="view.evidence.saved" role="status">{{ copy.evidenceSaved }}</BsText><BsText v-if="view.evidence.filenames.length" emphasis="semibold">{{ copy.evidenceAttached }}</BsText><BsList><BsListItem v-for="name in view.evidence.filenames" :key="name">{{ name }}</BsListItem></BsList></BsStack><BsText v-else role="status" tone="muted">{{ copy.evidenceFirst }}</BsText></BsContentSection>
      </section>
      <template v-else>
      <BsContentSection v-if="view.instructions" :title="copy.instructions" :description="copy.instructionsHelp"><BsText size="xs" emphasis="semibold">{{ copy.manual }}</BsText><BsGrid v-if="view.instructions.recipient || view.instructions.link || view.instructions.qr || view.instructions.text" :columns="2"><BsBox v-if="view.instructions.recipient"><BsText tone="muted">{{ copy.recipient }}</BsText><BsText dir="ltr" emphasis="bold">{{ view.instructions.recipient }}</BsText></BsBox><BsBox v-if="view.instructions.link"><BsText tone="muted">{{ copy.paymentLink }}</BsText><BsLink :to="view.instructions.link" target="_blank" rel="noopener noreferrer" external>{{ view.instructions.link }}</BsLink></BsBox><BsBox v-if="view.instructions.qr"><BsText tone="muted">{{ copy.qr }}</BsText><BsImage :src="view.instructions.qr" :alt="copy.qr"/></BsBox><BsText v-if="view.instructions.text">{{ view.instructions.text }}</BsText></BsGrid><BsText v-else tone="muted">{{ copy.instructionsUnavailable }}</BsText></BsContentSection>
      <BsContentSection v-if="view.privateOffer" data-private-offer :title="copy.privateTitle" :description="copy.privateHelp"><BsForm :pending="view.privateOffer.pending" :error="view.privateOffer.error" @submit="emit('privatePreview')"><BsField v-slot="control" :label="copy.privateLink"><BsInput :id="control.id" :model-value="form.privateLink" type="password" autocomplete="off" maxlength="2048" @update:model-value="value => field('privateLink', value)"/></BsField><BsButton type="submit" :pending="view.privateOffer.pending">{{ copy.privatePreview }}</BsButton></BsForm><BsStack v-if="view.privateOffer.title" data-private-offer-preview><BsHeading :level="3">{{ view.privateOffer.title }}</BsHeading><BsText>{{ view.privateOffer.summary }}</BsText><BsList><BsListItem v-for="limit in view.privateOffer.limits" :key="limit.key">{{ limit.label }}: {{ limit.value }}</BsListItem></BsList><BsText v-if="view.privateOffer.notice" role="status">{{ view.privateOffer.notice }}</BsText><BsText v-if="view.privateOffer.redeemed" role="status">{{ view.privateOffer.redeemed }}</BsText><BsButton variant="text" @click="emit('privateClear')">{{ copy.privateClear }}</BsButton></BsStack></BsContentSection>
      <BsContentSection v-if="view.transfer" :title="copy.notice" :description="copy.noticeHelp"><BsButton :disabled="view.transfer.disabled" @click="emit('transferOpen')">{{ copy.submit }}</BsButton></BsContentSection>
      <BsContentSection v-if="view.showEvidence" data-payment-evidence :title="copy.evidenceTitle" :description="copy.evidenceHelp"><BsStack v-if="view.evidence"><BsText>{{ copy.reference }}: {{ view.evidence.reference }}</BsText><BsForm :pending="view.evidence.pending" :error="view.evidence.error" @submit="emit('evidenceUpload')"><BsField for="payment-receipt" :label="copy.evidenceSelect"><BsFileInput :key="view.evidence.inputVersion" input-id="payment-receipt" :model-value="evidenceFile" :label="copy.evidenceSelect" accept="image/jpeg,image/png,image/webp" required @change="emit('evidenceSelect', $event)"/></BsField><BsButton type="submit" :pending="view.evidence.pending" :disabled="!evidenceFile">{{ view.evidence.pending ? copy.evidenceUploading : copy.evidenceUpload }}</BsButton></BsForm><BsText v-if="view.evidence.saved" role="status">{{ copy.evidenceSaved }}</BsText><BsText v-if="view.evidence.filenames.length" emphasis="semibold">{{ copy.evidenceAttached }}</BsText><BsList><BsListItem v-for="name in view.evidence.filenames" :key="name">{{ name }}</BsListItem></BsList></BsStack><BsText v-else role="status" tone="muted">{{ copy.evidenceFirst }}</BsText></BsContentSection>
      </template>
      <BsContentSection v-if="view.checkoutHistory" data-testid="checkout-history" :title="view.checkoutHistory.title"><BsDataTable :value="view.checkoutHistory.rows" data-key="id" :label="view.checkoutHistory.title" :columns="[{ key: 'status', field: 'status', header: view.checkoutHistory.status }, { key: 'plan', field: 'plan', header: view.checkoutHistory.plan }, { key: 'amount', field: 'amount', header: view.checkoutHistory.amount }, { key: 'date', field: 'date', header: view.checkoutHistory.date }]"><template #empty><BsText tone="muted">{{ view.checkoutHistory.empty }}</BsText></template></BsDataTable></BsContentSection>
      <BsContentSection v-if="view.showHistory" id="history" :title="copy.history"><BsDataTable :value="view.history" data-key="id" :label="copy.history" :columns="[{ key: 'status', header: copy.access }, { key: 'plan', field: 'plan', header: copy.requestedPlan }, { key: 'expected', field: 'expected', header: copy.expected }, { key: 'paid', field: 'paid', header: copy.paid }, { key: 'reference', field: 'reference', header: copy.reference }, { key: 'date', field: 'date', header: copy.transferDate }, { key: 'reason', field: 'reason', header: copy.reviewReason }]"><template #cell-status="{ row }"><BsStatusBadge :status="row.status"/><BsText>{{ row.statusLabel }}</BsText></template><template #empty><BsText tone="muted">{{ copy.empty }}</BsText></template></BsDataTable></BsContentSection>
    </template><BsStateSurface v-else state="empty" :title="copy.unavailable"/>
    <BsRecordActionDialog v-if="view.transfer" :visible="view.transfer.visible" :title="copy.notice" :dirty="view.transfer.dirty" :pending="view.transfer.pending" :error="view.transfer.error" :submit-label="copy.submit" :cancel-label="copy.cancel" :submit-disabled="view.transfer.disabled" @update:visible="value => { if (!value) emit('transferClose') }" @submit="emit('transferSubmit')"><BsText v-if="view.transfer.quote">{{ view.transfer.quote }}</BsText><BsText v-if="view.transfer.quoteNotice" tone="warning">{{ view.transfer.quoteNotice }}</BsText><BsText v-if="!view.transfer.quote" role="status">{{ copy.noPurchasable }}</BsText><BsField v-slot="control" :label="copy.paid"><BsInput :id="control.id" :model-value="form.paidAmount" :aria-describedby="control.describedby" type="number" :min="0.01" :step="0.01" :disabled="!view.transfer.quote" required @update:model-value="field('paidAmount', $event)"/></BsField><BsField v-slot="control" :label="copy.transferDate"><BsInput :id="control.id" :model-value="form.transferDate" :aria-describedby="control.describedby" type="date" :max="view.transfer.maximumDate" :disabled="!view.transfer.quote" required @update:model-value="field('transferDate', $event)"/></BsField><BsField v-slot="control" :label="copy.reference"><BsInput :id="control.id" :model-value="form.transferReference" :aria-describedby="control.describedby" dir="ltr" :minlength="2" :maxlength="200" :disabled="!view.transfer.quote" required @update:model-value="field('transferReference', $event)"/></BsField><BsText size="sm" tone="muted">{{ copy.policyPrefix }} <BsLink to="/terms">{{ copy.terms }}</BsLink> · <BsLink to="/privacy">{{ copy.privacy }}</BsLink> · <BsLink to="/refund-cancellation">{{ copy.refund }}</BsLink>.</BsText></BsRecordActionDialog>
    <BsManualPaymentDialog v-if="manual" :copy="copy" :view="manual" :reason="form.reason" @update:reason="field('reason', $event)" @close="emit('manualClose')" @refresh="emit('manualRefresh')" @select="emit('manualSelect', $event)" @file="emit('manualFile', $event)" @submit="emit('manualSubmit')" @cancel="emit('manualCancel')" @download="emit('manualDownload', $event)" @open-subscription="emit('openSubscription')"/>
    <BsPlanImpactDialog v-if="impact" :view="impact" @close="emit('impactClose')"/>
  </BsStack>
</template>

<style scoped>
.bs-billing-page--shop :deep(section[id]) { scroll-margin-block-start: 6rem; }
.bs-billing-payment { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; gap: 1rem; }
.bs-billing-payment__status { grid-column: 1 / -1; }
.bs-billing-provider-logo { display: inline-flex; }
.bs-billing-provider-logo__dark { display: none; }
:global(.dark .bs-billing-provider-logo__light) { display: none; }
:global(.dark .bs-billing-provider-logo__dark) { display: block; }
@media (max-width: 767px) { .bs-billing-payment { grid-template-columns: minmax(0, 1fr); } }
</style>
